    def pair_data(x):
        p = unpack(x)
        delta = p[ii] - p[jj]
        return np.einsum("ij,ij->i", delta, delta), delta

    def distances2(x):
        return pair_data(x)[0]

    def constraints(x):
        d2 = distances2(x)
        return np.concatenate((d2 - x[-1], 1.0 - d2))

    def constraint_jacobian(x):
