        grad = np.zeros((m, 36))
        rows = np.arange(m)
        left = ii >= 2
        right = jj >= 2

        for axis in range(3):
            grad[rows[left], 3 * (ii[left] - 2) + axis] = (
                2.0 * delta[left, axis]
            )
            grad[rows[right], 3 * (jj[right] - 2) + axis] = (
                -2.0 * delta[right, axis]
            )

        return np.vstack((
            np.column_stack((grad, -np.ones(m))),
            np.column_stack((-grad, np.zeros(m))),
        ))
